<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\ConsentPurposeKeyVO;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurposeKeyOptions;

trait ConsentPurposeKeyAttributeHolder
{
    protected ConsentPurposeKeyVO|ConsentPurposeKeyOptions|null $key = null;
    protected bool $keyAssigned = false;

    public function getKeyOrCurrent(ConsentPurposeKeyVO $key): ConsentPurposeKeyVO
    {
        if ($this->keyAssigned) {
            \assert(null !== $this->key);
            return ConsentPurposeKeyVO::from($this->key);
        } else {
            return $key;
        }
    }
    public function keyTryBuildInitial(ConstraintFailList $error): ?ConsentPurposeKeyVO
    {
        return  ConsentPurposeKeyVO::tryFrom($this->keyAssigned ? $this->key : null, $error);
    }
    public function key(ConsentPurposeKeyVO|ConsentPurposeKeyOptions $key): static
    {
        $this->key = $key;
        $this->keyAssigned = true;
        return $this;
    }
    public function getKey(): ?ConsentPurposeKeyOptions
    {
        return $this->key instanceof ConsentPurposeKeyVO ? $this->key->value() : $this->key;
    }
    public function isKeyAssigned(): bool
    {
        return $this->keyAssigned;
    }
    public function writeKeyTo(mixed $att): void
    {
        if ($this->keyAssigned) {
            \assert(null !== $this->key);
            $att->key($this->key);
        }
    }
    public function readKeyFrom(mixed $att): void
    {
        if ($att->isKeyAssigned()) {
            $key = $att->getKey();
            \assert(null !== $key);
            $this->key($key);
        }
    }
    public function unsetKey(): static
    {
        $this->keyAssigned = false;
        return $this;
    }
    protected function withDefaultKey(): void
    {
    }
    protected function withAssertedKeyRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->keyAssigned = $this->keyAssigned) {
            $value->key = ConsentPurposeKeyVO::tryFrom($this->key, $errorsList);
        }
    }
}
